"""Rebuild Table 1 (caption, header, rows) between the TABLE1 markers in wdd_tmlr.tex from results/exp_z2_ci.json.
FVU columns are over the typical states (exp_z2_recompute); the sink states appear as a share and their own FVU."""
import json, os, pathlib
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'results')
Z = json.load(open(f'{R}/exp_z2_ci.json'))
MODELS = [('gpt2', 'GPT-2 small, 124M'), ('smollm2-135m', 'SmolLM2-135M'), ('qwen2.5-0.5b', 'Qwen2.5-0.5B'), ('pythia-410m', 'Pythia-410m'), ('olmo-1b-0724', 'OLMo-1B'), ('qwen2.5-7b', 'Qwen2.5-7B'), ('llama-7b', 'Llama-7B'), ('pythia-6.9b', 'Pythia-6.9B')]
def ci(key, m, nd=3):
    c = Z[f'{key}/wikitext']['ci'][m]; return f"{c['point']:.{nd}f} [{c['lo']:.{nd}f}, {c['hi']:.{nd}f}]"
def pt(key, m, nd=3): return f"{Z[f'{key}/wikitext']['ci'][m]['point']:.{nd}f}"
def dec(key):
    v = [Z[f'{key}/wikitext']['ci'][f'r_decile_{d}']['point'] for d in range(1, 10)]; return f"{min(v):.2f} to {max(v):.2f}"
rows = []
for key, nm in MODELS:
    if f'{key}/wikitext' not in Z: continue
    e = Z[f'{key}/wikitext']
    cal = e['calibration']
    rows.append(f"{nm} & {ci(key, 'fvu32_weight_typical')} & {pt(key, 'fvu64_weight_typical')} & {pt(key, 'fvu32_rotated_typical')} & {100 * e['sink_variance_share']:.0f}\\% & {pt(key, 'fvu32_weight_sink', 4)} / {pt(key, 'fvu32_rotated_sink', 2)} & {ci(key, 'recall_top1_omp')} & {100 * cal['sign_agreement']['point']:.1f}\\% & {cal['median_rel_error']['point']:.2f} [{cal['median_rel_error']['lo']:.2f}, {cal['median_rel_error']['hi']:.2f}] & {cal['deciles'][0]['median_ratio']:.2f} / {cal['deciles'][9]['median_ratio']:.2f} \\\\")
    if key == 'olmo-1b-0724' and any(f'{k}/wikitext' in Z for k, _ in MODELS[5:]): rows.append('\\midrule')
caption = ("Eight models at their middle layers on WikiText-2, one protocol throughout: 32{,}768 evaluation states per model, brackets are 95\\% bootstrap intervals over the 64 evaluation sequences. "
           "FVU is over the typical states. The one to four sink states per sequence, whose norm exceeds ten times the median, carry the stated share of the variance and the weight dictionary reconstructs them almost exactly, so their FVU at $k=32$ is listed separately as weight / rotated. "
           "Recall is OMP-mode top-1 identification of each token's largest write. The last three columns describe the identified dominant writes on typical states: the share whose sign is recovered, the median relative error of the recovered coefficient, and the median ratio of recovered to true coefficient in the smallest and the largest magnitude decile. "
           "The 7B-class rows were run in bfloat16 (float32 control in Appendix~\\ref{app:fp32}).")
block = ("% TABLE1-BEGIN (regenerated by tools/splice_table1.py from exp_z2_ci.json; do not edit by hand)\n"
         "\\caption{" + caption + "}\n"
         "\\label{tab:families}\n"
         "\\begin{adjustbox}{max width=\\linewidth}\n\\begin{tabular}{lcccccccccc}\n\\toprule\n"
         "Model & FVU at $k=32$ & at $k=64$ & rotated, $k=32$ & sink share & sink FVU & top-1 recall & sign & median rel. error & ratio, deciles 1 / 10 \\\\\n\\midrule\n"
         + '\n'.join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{adjustbox}\n% TABLE1-END\n")
p = pathlib.Path('wdd_tmlr.tex'); s = p.read_text()
i = s.index('% TABLE1-BEGIN'); j = s.index('% TABLE1-END') + len('% TABLE1-END\n')
p.write_text(s[:i] + block + s[j:]); print('Table 1 rebuilt with', len([r for r in rows if r != '\\midrule']), 'rows')
